PRAGMA foreign_keys = ON;
ALTER TABLE vocabulary_items ADD COLUMN catalog_stage TEXT;
ALTER TABLE vocabulary_items ADD COLUMN catalog_source TEXT;
ALTER TABLE vocabulary_items ADD COLUMN catalog_topic TEXT;
ALTER TABLE vocabulary_items ADD COLUMN is_catalog INTEGER NOT NULL DEFAULT 0;
ALTER TABLE vocabulary_items ADD COLUMN search_text TEXT;
CREATE INDEX IF NOT EXISTS idx_vocabulary_catalog ON vocabulary_items(is_catalog,catalog_stage,entry_type,normalized_text);
CREATE TABLE IF NOT EXISTS vocabulary_catalog_stages (
  vocabulary_id TEXT NOT NULL REFERENCES vocabulary_items(id) ON DELETE CASCADE,
  stage TEXT NOT NULL,
  PRIMARY KEY(vocabulary_id,stage)
);
CREATE INDEX IF NOT EXISTS idx_vocabulary_catalog_stages_stage ON vocabulary_catalog_stages(stage,vocabulary_id);
CREATE TABLE IF NOT EXISTS learner_language_preferences (
  child_id TEXT PRIMARY KEY REFERENCES child_profiles(id) ON DELETE CASCADE,
  vocabulary_stage TEXT NOT NULL DEFAULT 'P6',
  grammar_stage TEXT NOT NULL DEFAULT 'P6',
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS vocabulary_catalog_progress (
  child_id TEXT NOT NULL REFERENCES child_profiles(id) ON DELETE CASCADE,
  vocabulary_id TEXT NOT NULL REFERENCES vocabulary_items(id) ON DELETE CASCADE,
  mastery REAL NOT NULL DEFAULT 0,
  seen_count INTEGER NOT NULL DEFAULT 0,
  correct_count INTEGER NOT NULL DEFAULT 0,
  last_practiced_at TEXT,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY(child_id,vocabulary_id)
);
CREATE TABLE IF NOT EXISTS vocabulary_practice_events (
  id TEXT PRIMARY KEY,
  child_id TEXT NOT NULL REFERENCES child_profiles(id) ON DELETE CASCADE,
  vocabulary_id TEXT REFERENCES vocabulary_items(id) ON DELETE SET NULL,
  stage TEXT NOT NULL,
  activity_type TEXT NOT NULL CHECK(activity_type IN ('choice','context_choice','reading')),
  correct INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS vocabulary_reinforcement_passages (
  id TEXT PRIMARY KEY,
  stage TEXT NOT NULL,
  title TEXT NOT NULL,
  body_text TEXT NOT NULL,
  target_terms_json TEXT NOT NULL DEFAULT '[]',
  questions_json TEXT NOT NULL DEFAULT '[]',
  status TEXT NOT NULL DEFAULT 'published',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS grammar_topics (
  id TEXT PRIMARY KEY,
  stage TEXT NOT NULL,
  topic_order INTEGER NOT NULL,
  category TEXT NOT NULL,
  title TEXT NOT NULL,
  summary TEXT NOT NULL,
  explanation_json TEXT NOT NULL DEFAULT '{}',
  objectives_json TEXT NOT NULL DEFAULT '[]',
  examples_json TEXT NOT NULL DEFAULT '[]',
  common_mistakes_json TEXT NOT NULL DEFAULT '[]',
  source_note TEXT,
  status TEXT NOT NULL DEFAULT 'published',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_grammar_topics_stage ON grammar_topics(stage,status,topic_order);
CREATE TABLE IF NOT EXISTS grammar_exercises (
  id TEXT PRIMARY KEY,
  topic_id TEXT NOT NULL REFERENCES grammar_topics(id) ON DELETE CASCADE,
  stage TEXT NOT NULL,
  modality TEXT NOT NULL CHECK(modality IN ('reading','writing','listening','speaking')),
  exercise_type TEXT NOT NULL,
  prompt_json TEXT NOT NULL,
  answer_json TEXT NOT NULL,
  explanation_json TEXT NOT NULL DEFAULT '{}',
  marks REAL NOT NULL DEFAULT 1,
  status TEXT NOT NULL DEFAULT 'published',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_grammar_exercises_topic ON grammar_exercises(topic_id,status);
CREATE TABLE IF NOT EXISTS grammar_topic_progress (
  child_id TEXT NOT NULL REFERENCES child_profiles(id) ON DELETE CASCADE,
  topic_id TEXT NOT NULL REFERENCES grammar_topics(id) ON DELETE CASCADE,
  mastery REAL NOT NULL DEFAULT 0,
  attempts INTEGER NOT NULL DEFAULT 0,
  correct_attempts INTEGER NOT NULL DEFAULT 0,
  last_practiced_at TEXT,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY(child_id,topic_id)
);
CREATE TABLE IF NOT EXISTS grammar_attempts (
  id TEXT PRIMARY KEY,
  child_id TEXT NOT NULL REFERENCES child_profiles(id) ON DELETE CASCADE,
  exercise_id TEXT NOT NULL REFERENCES grammar_exercises(id) ON DELETE CASCADE,
  response_json TEXT NOT NULL DEFAULT '{}',
  score REAL NOT NULL DEFAULT 0,
  max_score REAL NOT NULL DEFAULT 1,
  feedback_json TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
