INSERT OR IGNORE INTO vocabulary_reinforcement_passages (id,stage,title,body_text,target_terms_json,questions_json) VALUES ('vpass-p1p4-01','P1-P4','The Lost Water Bottle','During recess, Hana noticed a tiny blue water bottle under a bench. She was curious about its owner, so she asked her classmates at once. A cheerful Primary Three pupil came forward and described the bottle. Hana was careful to check the name tag before returning it. Her teacher praised her for looking after someone else’s belongings.','["tiny","curious","at once","cheerful","careful","look after"]', '[{"prompt":"In this passage, what does “tiny” most nearly mean?","options":["very small","wanting to know or learn something","taking care to avoid mistakes or danger","very large"],"correctOption":0,"explanation":"In context, “tiny” means very small."},{"prompt":"Which statement best describes the main idea?","options":["The passage develops one clear situation and shows how the people respond to it.","The passage is mainly a list of unrelated facts.","The passage explains how to solve a mathematics problem.","The passage argues that school rules should be removed."],"correctOption":0,"explanation":"The details centre on one situation and the response to it."}]');
INSERT OR IGNORE INTO vocabulary_reinforcement_passages (id,stage,title,body_text,target_terms_json,questions_json) VALUES ('vpass-p1p4-02','P1-P4','A Garden Surprise','The class gathered near the school garden to observe a new butterfly. At first, everyone wanted to stand in front of the flower bed. Their teacher reminded them to take turns and protect the plants. As soon as the butterfly opened its wings, the pupils became very quiet and watched with delight.','["gather","in front of","take turns","protect","as soon as"]', '[{"prompt":"In this passage, what does “gather” most nearly mean?","options":["to bring things or people together","wanting to know or learn something","taking care to avoid mistakes or danger","very large"],"correctOption":0,"explanation":"In context, “gather” means to bring things or people together."},{"prompt":"Which statement best describes the main idea?","options":["The passage develops one clear situation and shows how the people respond to it.","The passage is mainly a list of unrelated facts.","The passage explains how to solve a mathematics problem.","The passage argues that school rules should be removed."],"correctOption":0,"explanation":"The details centre on one situation and the response to it."}]');
INSERT OR IGNORE INTO vocabulary_reinforcement_passages (id,stage,title,body_text,target_terms_json,questions_json) VALUES ('vpass-p5-01','P5','The Reusable Cup Challenge','At first, Marcus was reluctant to join the class challenge because he often forgot his reusable cup. His partner persuaded him to keep an eye on it by placing it beside his school bag. Eventually, remembering the cup became a habit. Marcus began to appreciate how small choices could contribute to reducing waste.','["reluctant","persuade","keep an eye on","eventually","appreciate","contribute"]', '[{"prompt":"In this passage, what does “reluctant” most nearly mean?","options":["not willing or eager to do something","to watch carefully","to make someone agree by giving reasons","extremely tired"],"correctOption":0,"explanation":"In context, “reluctant” means not willing or eager to do something."},{"prompt":"Which statement best describes the main idea?","options":["The passage develops one clear situation and shows how the people respond to it.","The passage is mainly a list of unrelated facts.","The passage explains how to solve a mathematics problem.","The passage argues that school rules should be removed."],"correctOption":0,"explanation":"The details centre on one situation and the response to it."}]');
INSERT OR IGNORE INTO vocabulary_reinforcement_passages (id,stage,title,body_text,target_terms_json,questions_json) VALUES ('vpass-p5-02','P5','The Missing Key','When a storeroom key disappeared, the monitor did not accuse anyone. Instead, she decided to investigate carefully. She observed where each group had worked and asked calm questions. In the meantime, another pupil found the key under a stack of worksheets. Everyone was fortunate that the problem was solved quickly.','["investigate","observe","in the meantime","fortunate"]', '[{"prompt":"In this passage, what does “investigate” most nearly mean?","options":["to examine something carefully to discover facts","not willing or eager to do something","to watch carefully","to make someone agree by giving reasons"],"correctOption":0,"explanation":"In context, “investigate” means to examine something carefully to discover facts."},{"prompt":"Which statement best describes the main idea?","options":["The passage develops one clear situation and shows how the people respond to it.","The passage is mainly a list of unrelated facts.","The passage explains how to solve a mathematics problem.","The passage argues that school rules should be removed."],"correctOption":0,"explanation":"The details centre on one situation and the response to it."}]');
INSERT OR IGNORE INTO vocabulary_reinforcement_passages (id,stage,title,body_text,target_terms_json,questions_json) VALUES ('vpass-p6-01','P6','Planning for Heavy Rain','The weather forecast began to deteriorate before the outdoor event. The organisers had to take the forecast into account and decide whether to continue. They concluded that safety was more significant than convenience. As a result, the event moved indoors. The decision helped preserve the programme while reducing risk.','["deteriorate","take into account","significant","as a result","preserve"]', '[{"prompt":"In this passage, what does “deteriorate” most nearly mean?","options":["to become worse","important or large enough to be noticed","certain to happen and difficult to avoid","to give a good reason for something"],"correctOption":0,"explanation":"In context, “deteriorate” means to become worse."},{"prompt":"Which statement best describes the main idea?","options":["The passage develops one clear situation and shows how the people respond to it.","The passage is mainly a list of unrelated facts.","The passage explains how to solve a mathematics problem.","The passage argues that school rules should be removed."],"correctOption":0,"explanation":"The details centre on one situation and the response to it."}]');
INSERT OR IGNORE INTO vocabulary_reinforcement_passages (id,stage,title,body_text,target_terms_json,questions_json) VALUES ('vpass-p6-02','P6','Reading Between the Lines','In a story, the main character repeatedly checks the clock and avoids eye contact. The writer never says that he is anxious. A careful reader can infer his feelings from these details. To justify the inference, the reader should point to specific evidence rather than simply state a guess.','["infer","justify","evidence"]', '[{"prompt":"In this passage, what does “infer” most nearly mean?","options":["to reach a conclusion from evidence rather than direct statements","important or large enough to be noticed","certain to happen and difficult to avoid","to give a good reason for something"],"correctOption":0,"explanation":"In context, “infer” means to reach a conclusion from evidence rather than direct statements."},{"prompt":"Which statement best describes the main idea?","options":["The passage develops one clear situation and shows how the people respond to it.","The passage is mainly a list of unrelated facts.","The passage explains how to solve a mathematics problem.","The passage argues that school rules should be removed."],"correctOption":0,"explanation":"The details centre on one situation and the response to it."}]');
INSERT OR IGNORE INTO vocabulary_reinforcement_passages (id,stage,title,body_text,target_terms_json,questions_json) VALUES ('vpass-s1-01','S1','A School Campaign','A student group wanted to raise awareness of food waste. They analysed canteen habits and collected relevant evidence before designing posters. Their campaign presented the issue from several points of view and used precise examples. In addition to giving advice, the posters explained why small changes could play a role in reducing waste.','["raise awareness","analyse","relevant","evidence","point of view","precise","in addition to","play a role"]', '[{"prompt":"In this passage, what does “raise awareness” most nearly mean?","options":["to help more people understand an issue","to examine something carefully by considering its parts","a particular way of viewing a situation","closely connected to the topic or purpose"],"correctOption":0,"explanation":"In context, “raise awareness” means to help more people understand an issue."},{"prompt":"Which statement best describes the main idea?","options":["The passage develops one clear situation and shows how the people respond to it.","The passage is mainly a list of unrelated facts.","The passage explains how to solve a mathematics problem.","The passage argues that school rules should be removed."],"correctOption":0,"explanation":"The details centre on one situation and the response to it."}]');
INSERT OR IGNORE INTO vocabulary_reinforcement_passages (id,stage,title,body_text,target_terms_json,questions_json) VALUES ('vpass-s1-02','S1','Reading a Review Critically','A review may sound confident without being fully reliable. Readers should evaluate the writer’s evidence and consider what the writer may assume. A coherent review connects each judgement to a clear example. In response to strong evidence, readers may change their own interpretation.','["evaluate","assume","coherent","in response to","interpret"]', '[{"prompt":"In this passage, what does “evaluate” most nearly mean?","options":["to judge quality, value or effectiveness using reasons","to examine something carefully by considering its parts","a particular way of viewing a situation","closely connected to the topic or purpose"],"correctOption":0,"explanation":"In context, “evaluate” means to judge quality, value or effectiveness using reasons."},{"prompt":"Which statement best describes the main idea?","options":["The passage develops one clear situation and shows how the people respond to it.","The passage is mainly a list of unrelated facts.","The passage explains how to solve a mathematics problem.","The passage argues that school rules should be removed."],"correctOption":0,"explanation":"The details centre on one situation and the response to it."}]');
INSERT OR IGNORE INTO vocabulary_reinforcement_passages (id,stage,title,body_text,target_terms_json,questions_json) VALUES ('vpass-s2-01','S2','Checking Online Claims','Before sharing an online claim, assess whether the source is credible. Consider possible bias and look at the context in which the information was produced. A single example may not be sufficient. By contrast, several independent sources that are consistent with one another can reinforce confidence in a conclusion.','["assess","credible","bias","context","sufficient","by contrast","consistent","reinforce"]', '[{"prompt":"In this passage, what does “assess” most nearly mean?","options":["to judge the quality, importance or effect of something","to develop or express an idea carefully","an unfair preference that affects judgement","believable and trustworthy"],"correctOption":0,"explanation":"In context, “assess” means to judge the quality, importance or effect of something."},{"prompt":"Which statement best describes the main idea?","options":["The passage develops one clear situation and shows how the people respond to it.","The passage is mainly a list of unrelated facts.","The passage explains how to solve a mathematics problem.","The passage argues that school rules should be removed."],"correctOption":0,"explanation":"The details centre on one situation and the response to it."}]');
INSERT OR IGNORE INTO vocabulary_reinforcement_passages (id,stage,title,body_text,target_terms_json,questions_json) VALUES ('vpass-s2-02','S2','Why Habits Matter','People sometimes take useful routines for granted. Yet small daily choices can account for a large difference in the long run. Sleep, exercise and focused revision are related to learning in different ways. Looking at these habits in relation to one another can shed light on why performance changes over time.','["take for granted","account for","in the long run","in relation to","shed light on"]', '[{"prompt":"In this passage, what does “take for granted” most nearly mean?","options":["to accept something as true or available without thinking about it","to develop or express an idea carefully","to judge the quality, importance or effect of something","an unfair preference that affects judgement"],"correctOption":0,"explanation":"In context, “take for granted” means to accept something as true or available without thinking about it."},{"prompt":"Which statement best describes the main idea?","options":["The passage develops one clear situation and shows how the people respond to it.","The passage is mainly a list of unrelated facts.","The passage explains how to solve a mathematics problem.","The passage argues that school rules should be removed."],"correctOption":0,"explanation":"The details centre on one situation and the response to it."}]');
INSERT OR IGNORE INTO vocabulary_reinforcement_passages (id,stage,title,body_text,target_terms_json,questions_json) VALUES ('vpass-s3-01','S3','Balancing Two Priorities','A city may need to strike a balance between convenience and environmental impact. One group may advocate more parking, while another argues for better public transport. To a large extent, the best decision depends on local conditions. Decision-makers should weigh up the evidence and revise their plans in light of new information.','["strike a balance","advocate","to a large extent","weigh up","in light of"]', '[{"prompt":"In this passage, what does “strike a balance” most nearly mean?","options":["to find a reasonable position between competing needs","to express an idea clearly and effectively","to combine information from different sources into a new understanding","an argument that challenges another argument"],"correctOption":0,"explanation":"In context, “strike a balance” means to find a reasonable position between competing needs."},{"prompt":"Which statement best describes the main idea?","options":["The passage develops one clear situation and shows how the people respond to it.","The passage is mainly a list of unrelated facts.","The passage explains how to solve a mathematics problem.","The passage argues that school rules should be removed."],"correctOption":0,"explanation":"The details centre on one situation and the response to it."}]');
INSERT OR IGNORE INTO vocabulary_reinforcement_passages (id,stage,title,body_text,target_terms_json,questions_json) VALUES ('vpass-s3-02','S3','Building a Strong Argument','A rigorous argument does more than state an opinion. It articulates a clear claim, uses evidence to substantiate it and addresses a reasonable counterargument. From this perspective, disagreement can strengthen an essay because it forces the writer to reconcile competing ideas and produce a more plausible conclusion.','["rigorous","articulate","substantiate","counterargument","from this perspective","reconcile","plausible"]', '[{"prompt":"In this passage, what does “rigorous” most nearly mean?","options":["careful, thorough and accurate","to express an idea clearly and effectively","to combine information from different sources into a new understanding","an argument that challenges another argument"],"correctOption":0,"explanation":"In context, “rigorous” means careful, thorough and accurate."},{"prompt":"Which statement best describes the main idea?","options":["The passage develops one clear situation and shows how the people respond to it.","The passage is mainly a list of unrelated facts.","The passage explains how to solve a mathematics problem.","The passage argues that school rules should be removed."],"correctOption":0,"explanation":"The details centre on one situation and the response to it."}]');
INSERT OR IGNORE INTO vocabulary_reinforcement_passages (id,stage,title,body_text,target_terms_json,questions_json) VALUES ('vpass-s4-01','S4','Reading a Contentious Debate','A contentious debate often contains strong rhetoric. A careful reader should scrutinise the premise of each argument and notice any discrepancy between a claim and its evidence. It is worth noting that a compelling style does not make a claim true. A nuanced judgement may concede a valid point while still refuting the overall conclusion.','["contentious","rhetoric","scrutinise","premise","discrepancy","it is worth noting","compelling","nuanced","concede","refute"]', '[{"prompt":"In this passage, what does “contentious” most nearly mean?","options":["likely to cause disagreement","showing careful attention to subtle differences","strongly convincing or interesting","to admit that a point is true, often before presenting a different view"],"correctOption":0,"explanation":"In context, “contentious” means likely to cause disagreement."},{"prompt":"Which statement best describes the main idea?","options":["The passage develops one clear situation and shows how the people respond to it.","The passage is mainly a list of unrelated facts.","The passage explains how to solve a mathematics problem.","The passage argues that school rules should be removed."],"correctOption":0,"explanation":"The details centre on one situation and the response to it."}]');
INSERT OR IGNORE INTO vocabulary_reinforcement_passages (id,stage,title,body_text,target_terms_json,questions_json) VALUES ('vpass-s4-02','S4','Planning for Long-Term Impact','A sustainable policy should mitigate foreseeable harm rather than exacerbate it. With regard to cost, a cheaper short-term option may appear attractive, but it could give rise to larger expenses later. In the final analysis, leaders must consider both immediate needs and long-term implications.','["sustainable","mitigate","exacerbate","with regard to","give rise to","in the final analysis","implication"]', '[{"prompt":"In this passage, what does “sustainable” most nearly mean?","options":["able to continue over time without causing serious harm","showing careful attention to subtle differences","strongly convincing or interesting","to admit that a point is true, often before presenting a different view"],"correctOption":0,"explanation":"In context, “sustainable” means able to continue over time without causing serious harm."},{"prompt":"Which statement best describes the main idea?","options":["The passage develops one clear situation and shows how the people respond to it.","The passage is mainly a list of unrelated facts.","The passage explains how to solve a mathematics problem.","The passage argues that school rules should be removed."],"correctOption":0,"explanation":"The details centre on one situation and the response to it."}]');
INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-p1p4-01','P1-P4',1,'word and phrase','Nouns, pronouns & noun groups','Build clear noun groups and choose pronouns that match their nouns.','{"rule":"Use nouns to name people, places, things and ideas; use pronouns clearly so the reader knows what they refer to.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for nouns, pronouns & noun groups.","Apply nouns, pronouns & noun groups accurately in context.","Edit a common error involving nouns, pronouns & noun groups."]', '[{"label":"Accurate","sentence":"The children carried their bags into the hall."},{"label":"Needs editing","sentence":"The children carried his bags into the hall."},{"label":"Correction","sentence":"The children carried their bags into the hall."}]', '["Avoid: The children carried his bags into the hall.","Prefer: The children carried their bags into the hall."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-p1p4-01-a','gram-p1p4-01','P1-P4','reading','multiple_choice','{"title":"Choose the accurate sentence","prompt":"Which sentence best applies the rule for “Nouns, pronouns & noun groups”?","options":["The children carried their bags into the hall.","The children carried his bags into the hall.","The children carried his bags into the hall?","The children carried their bags into the hall. Extra."],"audioText":null}', '{"correctOption":0,"acceptedAnswers":["The children carried their bags into the hall."]}', '{"text":"Use nouns to name people, places, things and ideas; use pronouns clearly so the reader knows what they refer to."}');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-p1p4-01-b','gram-p1p4-01','P1-P4','writing','editing','{"title":"Edit the sentence","prompt":"Correct this sentence without changing its meaning: The children carried his bags into the hall.","modelText":"The children carried their bags into the hall.","speakFirst":false}', '{"acceptedAnswers":["The children carried their bags into the hall."],"modelAnswer":"The children carried their bags into the hall."}', '{"text":"Use nouns to name people, places, things and ideas; use pronouns clearly so the reader knows what they refer to. Model correction: The children carried their bags into the hall."}');
INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-p1p4-02','P1-P4',2,'word and phrase','Articles & determiners','Choose articles and determiners that fit the noun and meaning.','{"rule":"Use a, an, the and other determiners to show whether a noun is general, specific or counted.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for articles & determiners.","Apply articles & determiners accurately in context.","Edit a common error involving articles & determiners."]', '[{"label":"Accurate","sentence":"I saw an owl in the tree."},{"label":"Needs editing","sentence":"I saw a owl in the tree."},{"label":"Correction","sentence":"I saw an owl in the tree."}]', '["Avoid: I saw a owl in the tree.","Prefer: I saw an owl in the tree."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-p1p4-02-a','gram-p1p4-02','P1-P4','writing','multiple_choice','{"title":"Choose the accurate sentence","prompt":"Which sentence best applies the rule for “Articles & determiners”?","options":["I saw an owl in the tree.","I saw a owl in the tree.","I saw a owl in the tree?","I saw an owl in the tree. Extra."],"audioText":null}', '{"correctOption":0,"acceptedAnswers":["I saw an owl in the tree."]}', '{"text":"Use a, an, the and other determiners to show whether a noun is general, specific or counted."}');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-p1p4-02-b','gram-p1p4-02','P1-P4','writing','editing','{"title":"Edit the sentence","prompt":"Correct this sentence without changing its meaning: I saw a owl in the tree.","modelText":"I saw an owl in the tree.","speakFirst":false}', '{"acceptedAnswers":["I saw an owl in the tree."],"modelAnswer":"I saw an owl in the tree."}', '{"text":"Use a, an, the and other determiners to show whether a noun is general, specific or counted. Model correction: I saw an owl in the tree."}');
INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-p1p4-03','P1-P4',3,'word and phrase','Adjectives & description','Use adjective order and position to make descriptions natural.','{"rule":"Use adjectives to add precise details without overloading the noun phrase.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for adjectives & description.","Apply adjectives & description accurately in context.","Edit a common error involving adjectives & description."]', '[{"label":"Accurate","sentence":"The narrow wooden bridge crossed the stream."},{"label":"Needs editing","sentence":"The bridge narrow wooden crossed the stream."},{"label":"Correction","sentence":"The narrow wooden bridge crossed the stream."}]', '["Avoid: The bridge narrow wooden crossed the stream.","Prefer: The narrow wooden bridge crossed the stream."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
