INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-p1p4-04','P1-P4',4,'verb','Verbs & simple tenses','Match verb forms to the time of the action.','{"rule":"Use verb forms consistently to show present and past time.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for verbs & simple tenses.","Apply verbs & simple tenses accurately in context.","Edit a common error involving verbs & simple tenses."]', '[{"label":"Accurate","sentence":"Yesterday, Amir walked home and called his mother."},{"label":"Needs editing","sentence":"Yesterday, Amir walks home and called his mother."},{"label":"Correction","sentence":"Yesterday, Amir walked home and called his mother."}]', '["Avoid: Yesterday, Amir walks home and called his mother.","Prefer: Yesterday, Amir walked home and called his mother."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
