INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-p1p4-05','P1-P4',5,'sentence','Subject–verb agreement','Find the true subject before choosing the verb form.','{"rule":"Make the verb agree with the subject in number and person.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for subject–verb agreement.","Apply subject–verb agreement accurately in context.","Edit a common error involving subject–verb agreement."]', '[{"label":"Accurate","sentence":"The box of crayons is on the table."},{"label":"Needs editing","sentence":"The box of crayons are on the table."},{"label":"Correction","sentence":"The box of crayons is on the table."}]', '["Avoid: The box of crayons are on the table.","Prefer: The box of crayons is on the table."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-p1p4-05-a','gram-p1p4-05','P1-P4','reading','multiple_choice','{"title":"Choose the accurate sentence","prompt":"Which sentence best applies the rule for “Subject–verb agreement”?","options":["The box of crayons is on the table.","The box of crayons are on the table.","The box of crayons are on the table?","The box of crayons is on the table. Extra."],"audioText":null}', '{"correctOption":0,"acceptedAnswers":["The box of crayons is on the table."]}', '{"text":"Make the verb agree with the subject in number and person."}');
