INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-p1p4-06','P1-P4',6,'word and phrase','Prepositions of time & place','Choose prepositions according to the relationship you want to express.','{"rule":"Use prepositions to show relationships such as time, place and direction.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for prepositions of time & place.","Apply prepositions of time & place accurately in context.","Edit a common error involving prepositions of time & place."]', '[{"label":"Accurate","sentence":"We met at the gate on Monday."},{"label":"Needs editing","sentence":"We met in the gate at Monday."},{"label":"Correction","sentence":"We met at the gate on Monday."}]', '["Avoid: We met in the gate at Monday.","Prefer: We met at the gate on Monday."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-p1p4-06-a','gram-p1p4-06','P1-P4','writing','multiple_choice','{"title":"Choose the accurate sentence","prompt":"Which sentence best applies the rule for “Prepositions of time & place”?","options":["We met at the gate on Monday.","We met in the gate at Monday.","We met in the gate at Monday?","We met at the gate on Monday. Extra."],"audioText":null}', '{"correctOption":0,"acceptedAnswers":["We met at the gate on Monday."]}', '{"text":"Use prepositions to show relationships such as time, place and direction."}');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-p1p4-06-b','gram-p1p4-06','P1-P4','writing','editing','{"title":"Edit the sentence","prompt":"Correct this sentence without changing its meaning: We met in the gate at Monday.","modelText":"We met at the gate on Monday.","speakFirst":false}', '{"acceptedAnswers":["We met at the gate on Monday."],"modelAnswer":"We met at the gate on Monday."}', '{"text":"Use prepositions to show relationships such as time, place and direction. Model correction: We met at the gate on Monday."}');
INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-p1p4-07','P1-P4',7,'sentence','Connectors & sentence joining','Use connectors that match the logical relationship between ideas.','{"rule":"Join ideas with suitable connectors such as and, but, because, so and when.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for connectors & sentence joining.","Apply connectors & sentence joining accurately in context.","Edit a common error involving connectors & sentence joining."]', '[{"label":"Accurate","sentence":"We stayed indoors because it was raining."},{"label":"Needs editing","sentence":"We stayed indoors but it was raining."},{"label":"Correction","sentence":"We stayed indoors because it was raining."}]', '["Avoid: We stayed indoors but it was raining.","Prefer: We stayed indoors because it was raining."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-p1p4-07-a','gram-p1p4-07','P1-P4','listening','multiple_choice','{"title":"Choose the accurate sentence","prompt":"Which sentence best applies the rule for “Connectors & sentence joining”?","options":["We stayed indoors because it was raining.","We stayed indoors but it was raining.","We stayed indoors but it was raining?","We stayed indoors because it was raining. Extra."],"audioText":"We stayed indoors because it was raining."}', '{"correctOption":0,"acceptedAnswers":["We stayed indoors because it was raining."]}', '{"text":"Join ideas with suitable connectors such as and, but, because, so and when."}');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-p1p4-07-b','gram-p1p4-07','P1-P4','writing','editing','{"title":"Edit the sentence","prompt":"Correct this sentence without changing its meaning: We stayed indoors but it was raining.","modelText":"We stayed indoors because it was raining.","speakFirst":false}', '{"acceptedAnswers":["We stayed indoors because it was raining."],"modelAnswer":"We stayed indoors because it was raining."}', '{"text":"Join ideas with suitable connectors such as and, but, because, so and when. Model correction: We stayed indoors because it was raining."}');
INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-p1p4-08','P1-P4',8,'sentence','Questions, commands & punctuation','Use sentence type and punctuation to signal purpose clearly.','{"rule":"Use sentence forms and punctuation that match statements, questions, commands and exclamations.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for questions, commands & punctuation.","Apply questions, commands & punctuation accurately in context.","Edit a common error involving questions, commands & punctuation."]', '[{"label":"Accurate","sentence":"Please close the door before you leave."},{"label":"Needs editing","sentence":"Please close the door before you leave?"},{"label":"Correction","sentence":"Please close the door before you leave."}]', '["Avoid: Please close the door before you leave?","Prefer: Please close the door before you leave."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
