INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-p5-01','P5',1,'verb','Tense consistency in context','Control present and past verb forms across a whole sentence or passage.','{"rule":"Keep tenses consistent unless the time relationship changes.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for tense consistency in context.","Apply tense consistency in context accurately in context.","Edit a common error involving tense consistency in context."]', '[{"label":"Accurate","sentence":"When the bell rang, the pupils packed their bags and left."},{"label":"Needs editing","sentence":"When the bell rang, the pupils pack their bags and left."},{"label":"Correction","sentence":"When the bell rang, the pupils packed their bags and left."}]', '["Avoid: When the bell rang, the pupils pack their bags and left.","Prefer: When the bell rang, the pupils packed their bags and left."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
