INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-p5-02','P5',2,'sentence','Complex subject–verb agreement','Identify the main noun in longer subjects before choosing the verb.','{"rule":"Ignore interrupting phrases and make the verb agree with the head noun of the subject.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for complex subject–verb agreement.","Apply complex subject–verb agreement accurately in context.","Edit a common error involving complex subject–verb agreement."]', '[{"label":"Accurate","sentence":"A basket of ripe mangoes was on the counter."},{"label":"Needs editing","sentence":"A basket of ripe mangoes were on the counter."},{"label":"Correction","sentence":"A basket of ripe mangoes was on the counter."}]', '["Avoid: A basket of ripe mangoes were on the counter.","Prefer: A basket of ripe mangoes was on the counter."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
