INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-p5-02-b','gram-p5-02','P5','writing','editing','{"title":"Edit the sentence","prompt":"Correct this sentence without changing its meaning: A basket of ripe mangoes were on the counter.","modelText":"A basket of ripe mangoes was on the counter.","speakFirst":false}', '{"acceptedAnswers":["A basket of ripe mangoes was on the counter."],"modelAnswer":"A basket of ripe mangoes was on the counter."}', '{"text":"Ignore interrupting phrases and make the verb agree with the head noun of the subject. Model correction: A basket of ripe mangoes was on the counter."}');
INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-p5-03','P5',3,'verb','Modals for ability, advice & possibility','Use the base verb after a modal and choose a modal that matches the intended meaning.','{"rule":"Use modal verbs to express ability, obligation, advice, permission or possibility.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for modals for ability, advice & possibility.","Apply modals for ability, advice & possibility accurately in context.","Edit a common error involving modals for ability, advice & possibility."]', '[{"label":"Accurate","sentence":"You should check your answer before submitting it."},{"label":"Needs editing","sentence":"You should to check your answer before submitting it."},{"label":"Correction","sentence":"You should check your answer before submitting it."}]', '["Avoid: You should to check your answer before submitting it.","Prefer: You should check your answer before submitting it."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
