INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-p5-04','P5',4,'sentence','Relative clauses','Choose a relative word that matches the noun and function.','{"rule":"Use who, which, that, whose and where to add information about a noun.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for relative clauses.","Apply relative clauses accurately in context.","Edit a common error involving relative clauses."]', '[{"label":"Accurate","sentence":"The cyclist who helped us was wearing a red helmet."},{"label":"Needs editing","sentence":"The cyclist which helped us was wearing a red helmet."},{"label":"Correction","sentence":"The cyclist who helped us was wearing a red helmet."}]', '["Avoid: The cyclist which helped us was wearing a red helmet.","Prefer: The cyclist who helped us was wearing a red helmet."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-p5-04-a','gram-p5-04','P5','speaking','multiple_choice','{"title":"Choose the accurate sentence","prompt":"Which sentence best applies the rule for “Relative clauses”?","options":["The cyclist who helped us was wearing a red helmet.","The cyclist which helped us was wearing a red helmet.","The cyclist which helped us was wearing a red helmet?","The cyclist who helped us was wearing a red helmet. Extra."],"audioText":null}', '{"correctOption":0,"acceptedAnswers":["The cyclist who helped us was wearing a red helmet."]}', '{"text":"Use who, which, that, whose and where to add information about a noun."}');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-p5-04-b','gram-p5-04','P5','writing','editing','{"title":"Edit the sentence","prompt":"Correct this sentence without changing its meaning: The cyclist which helped us was wearing a red helmet.","modelText":"The cyclist who helped us was wearing a red helmet.","speakFirst":false}', '{"acceptedAnswers":["The cyclist who helped us was wearing a red helmet."],"modelAnswer":"The cyclist who helped us was wearing a red helmet."}', '{"text":"Use who, which, that, whose and where to add information about a noun. Model correction: The cyclist who helped us was wearing a red helmet."}');
INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-p5-05','P5',5,'sentence','Reported speech','Keep viewpoint and time relationships clear in reported speech.','{"rule":"Shift pronouns, time expressions and verb forms when reporting what someone said, where needed.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for reported speech.","Apply reported speech accurately in context.","Edit a common error involving reported speech."]', '[{"label":"Accurate","sentence":"Lina said that she was tired."},{"label":"Needs editing","sentence":"Lina said that I am tired."},{"label":"Correction","sentence":"Lina said that she was tired."}]', '["Avoid: Lina said that I am tired.","Prefer: Lina said that she was tired."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-p5-05-a','gram-p5-05','P5','reading','multiple_choice','{"title":"Choose the accurate sentence","prompt":"Which sentence best applies the rule for “Reported speech”?","options":["Lina said that she was tired.","Lina said that I am tired.","Lina said that I am tired?","Lina said that she was tired. Extra."],"audioText":null}', '{"correctOption":0,"acceptedAnswers":["Lina said that she was tired."]}', '{"text":"Shift pronouns, time expressions and verb forms when reporting what someone said, where needed."}');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-p5-05-b','gram-p5-05','P5','speaking','editing','{"title":"Edit the sentence","prompt":"Correct this sentence without changing its meaning: Lina said that I am tired.","modelText":"Lina said that she was tired.","speakFirst":true}', '{"acceptedAnswers":["Lina said that she was tired."],"modelAnswer":"Lina said that she was tired."}', '{"text":"Shift pronouns, time expressions and verb forms when reporting what someone said, where needed. Model correction: Lina said that she was tired."}');
INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-p5-06','P5',6,'sentence','Active & passive voice','Understand who performs the action and what the sentence should emphasise.','{"rule":"Choose active voice to focus on the doer and passive voice to focus on the action or receiver.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for active & passive voice.","Apply active & passive voice accurately in context.","Edit a common error involving active & passive voice."]', '[{"label":"Accurate","sentence":"The class collected the bottles for recycling."},{"label":"Needs editing","sentence":"The bottles collected the class for recycling."},{"label":"Correction","sentence":"The class collected the bottles for recycling."}]', '["Avoid: The bottles collected the class for recycling.","Prefer: The class collected the bottles for recycling."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-p5-06-a','gram-p5-06','P5','writing','multiple_choice','{"title":"Choose the accurate sentence","prompt":"Which sentence best applies the rule for “Active & passive voice”?","options":["The class collected the bottles for recycling.","The bottles collected the class for recycling.","The bottles collected the class for recycling?","The class collected the bottles for recycling. Extra."],"audioText":null}', '{"correctOption":0,"acceptedAnswers":["The class collected the bottles for recycling."]}', '{"text":"Choose active voice to focus on the doer and passive voice to focus on the action or receiver."}');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-p5-06-b','gram-p5-06','P5','writing','editing','{"title":"Edit the sentence","prompt":"Correct this sentence without changing its meaning: The bottles collected the class for recycling.","modelText":"The class collected the bottles for recycling.","speakFirst":false}', '{"acceptedAnswers":["The class collected the bottles for recycling."],"modelAnswer":"The class collected the bottles for recycling."}', '{"text":"Choose active voice to focus on the doer and passive voice to focus on the action or receiver. Model correction: The class collected the bottles for recycling."}');
INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-p5-07','P5',7,'sentence','Synthesis & transformation','Preserve meaning while changing sentence structure.','{"rule":"Combine or transform sentences without changing the original meaning.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for synthesis & transformation.","Apply synthesis & transformation accurately in context.","Edit a common error involving synthesis & transformation."]', '[{"label":"Accurate","sentence":"Although it was raining, the match continued."},{"label":"Needs editing","sentence":"Although it was raining. The match continued."},{"label":"Correction","sentence":"Although it was raining, the match continued."}]', '["Avoid: Although it was raining. The match continued.","Prefer: Although it was raining, the match continued."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
