INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-p5-07-b','gram-p5-07','P5','writing','editing','{"title":"Edit the sentence","prompt":"Correct this sentence without changing its meaning: Although it was raining. The match continued.","modelText":"Although it was raining, the match continued.","speakFirst":false}', '{"acceptedAnswers":["Although it was raining, the match continued."],"modelAnswer":"Although it was raining, the match continued."}', '{"text":"Combine or transform sentences without changing the original meaning. Model correction: Although it was raining, the match continued."}');
INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-p5-08','P5',8,'text','Grammar cloze: cohesion & clues','Read beyond the blank and use both grammatical and logical clues.','{"rule":"Use meaning, grammar and nearby clues together to choose the correct word or form.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for grammar cloze: cohesion & clues.","Apply grammar cloze: cohesion & clues accurately in context.","Edit a common error involving grammar cloze: cohesion & clues."]', '[{"label":"Accurate","sentence":"Although the path was steep, the hikers continued steadily."},{"label":"Needs editing","sentence":"Because the path was steep, but the hikers continued steadily."},{"label":"Correction","sentence":"Although the path was steep, the hikers continued steadily."}]', '["Avoid: Because the path was steep, but the hikers continued steadily.","Prefer: Although the path was steep, the hikers continued steadily."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
