INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-p6-01','P6',1,'verb','Perfect & progressive verb forms','Use aspect to show how actions relate in time.','{"rule":"Use perfect forms for completed relationships and progressive forms for actions in progress.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for perfect & progressive verb forms.","Apply perfect & progressive verb forms accurately in context.","Edit a common error involving perfect & progressive verb forms."]', '[{"label":"Accurate","sentence":"By noon, we had completed the first part of the project."},{"label":"Needs editing","sentence":"By noon, we have completed the first part yesterday."},{"label":"Correction","sentence":"By noon, we had completed the first part of the project."}]', '["Avoid: By noon, we have completed the first part yesterday.","Prefer: By noon, we had completed the first part of the project."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-p6-01-a','gram-p6-01','P6','reading','multiple_choice','{"title":"Choose the accurate sentence","prompt":"Which sentence best applies the rule for “Perfect & progressive verb forms”?","options":["By noon, we had completed the first part of the project.","By noon, we have completed the first part yesterday.","By noon, we have completed the first part yesterday?","By noon, we had completed the first part of the project. Extra."],"audioText":null}', '{"correctOption":0,"acceptedAnswers":["By noon, we had completed the first part of the project."]}', '{"text":"Use perfect forms for completed relationships and progressive forms for actions in progress."}');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-p6-01-b','gram-p6-01','P6','writing','editing','{"title":"Edit the sentence","prompt":"Correct this sentence without changing its meaning: By noon, we have completed the first part yesterday.","modelText":"By noon, we had completed the first part of the project.","speakFirst":false}', '{"acceptedAnswers":["By noon, we had completed the first part of the project."],"modelAnswer":"By noon, we had completed the first part of the project."}', '{"text":"Use perfect forms for completed relationships and progressive forms for actions in progress. Model correction: By noon, we had completed the first part of the project."}');
INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-p6-02','P6',2,'sentence','Conditionals','Match verb forms to the type of condition and intended meaning.','{"rule":"Use if-clauses and main clauses consistently to express real, possible or imagined conditions.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for conditionals.","Apply conditionals accurately in context.","Edit a common error involving conditionals."]', '[{"label":"Accurate","sentence":"If you revise regularly, you will remember more."},{"label":"Needs editing","sentence":"If you will revise regularly, you remember more."},{"label":"Correction","sentence":"If you revise regularly, you will remember more."}]', '["Avoid: If you will revise regularly, you remember more.","Prefer: If you revise regularly, you will remember more."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
