INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-p6-03','P6',3,'sentence','Reported questions','Remove question inversion when a question becomes reported speech.','{"rule":"In reported questions, use statement word order after the reporting phrase.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for reported questions.","Apply reported questions accurately in context.","Edit a common error involving reported questions."]', '[{"label":"Accurate","sentence":"I asked where the bus stop was."},{"label":"Needs editing","sentence":"I asked where was the bus stop."},{"label":"Correction","sentence":"I asked where the bus stop was."}]', '["Avoid: I asked where was the bus stop.","Prefer: I asked where the bus stop was."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-p6-03-a','gram-p6-03','P6','listening','multiple_choice','{"title":"Choose the accurate sentence","prompt":"Which sentence best applies the rule for “Reported questions”?","options":["I asked where the bus stop was.","I asked where was the bus stop.","I asked where was the bus stop?","I asked where the bus stop was. Extra."],"audioText":"I asked where the bus stop was."}', '{"correctOption":0,"acceptedAnswers":["I asked where the bus stop was."]}', '{"text":"In reported questions, use statement word order after the reporting phrase."}');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-p6-03-b','gram-p6-03','P6','writing','editing','{"title":"Edit the sentence","prompt":"Correct this sentence without changing its meaning: I asked where was the bus stop.","modelText":"I asked where the bus stop was.","speakFirst":false}', '{"acceptedAnswers":["I asked where the bus stop was."],"modelAnswer":"I asked where the bus stop was."}', '{"text":"In reported questions, use statement word order after the reporting phrase. Model correction: I asked where the bus stop was."}');
INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-p6-04','P6',4,'sentence','Passive voice for focus','Form passive verbs accurately and use them when the receiver should be emphasised.','{"rule":"Use be + past participle and keep tense and agreement correct.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for passive voice for focus.","Apply passive voice for focus accurately in context.","Edit a common error involving passive voice for focus."]', '[{"label":"Accurate","sentence":"The missing wallet was found by a cleaner."},{"label":"Needs editing","sentence":"The missing wallet was find by a cleaner."},{"label":"Correction","sentence":"The missing wallet was found by a cleaner."}]', '["Avoid: The missing wallet was find by a cleaner.","Prefer: The missing wallet was found by a cleaner."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
