INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-p6-04-b','gram-p6-04','P6','writing','editing','{"title":"Edit the sentence","prompt":"Correct this sentence without changing its meaning: The missing wallet was find by a cleaner.","modelText":"The missing wallet was found by a cleaner.","speakFirst":false}', '{"acceptedAnswers":["The missing wallet was found by a cleaner."],"modelAnswer":"The missing wallet was found by a cleaner."}', '{"text":"Use be + past participle and keep tense and agreement correct. Model correction: The missing wallet was found by a cleaner."}');
INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-p6-05','P6',5,'sentence','Complex sentences & clause control','Control clause boundaries in longer sentences.','{"rule":"Connect main and subordinate clauses without creating fragments or run-ons.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for complex sentences & clause control.","Apply complex sentences & clause control accurately in context.","Edit a common error involving complex sentences & clause control."]', '[{"label":"Accurate","sentence":"Although the road was flooded, the driver remained calm."},{"label":"Needs editing","sentence":"Although the road was flooded. The driver remained calm."},{"label":"Correction","sentence":"Although the road was flooded, the driver remained calm."}]', '["Avoid: Although the road was flooded. The driver remained calm.","Prefer: Although the road was flooded, the driver remained calm."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-p6-05-a','gram-p6-05','P6','reading','multiple_choice','{"title":"Choose the accurate sentence","prompt":"Which sentence best applies the rule for “Complex sentences & clause control”?","options":["Although the road was flooded, the driver remained calm.","Although the road was flooded. The driver remained calm.","Although the road was flooded? The driver remained calm?","Although the road was flooded, the driver remained calm. Extra."],"audioText":null}', '{"correctOption":0,"acceptedAnswers":["Although the road was flooded, the driver remained calm."]}', '{"text":"Connect main and subordinate clauses without creating fragments or run-ons."}');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-p6-05-b','gram-p6-05','P6','speaking','editing','{"title":"Edit the sentence","prompt":"Correct this sentence without changing its meaning: Although the road was flooded. The driver remained calm.","modelText":"Although the road was flooded, the driver remained calm.","speakFirst":true}', '{"acceptedAnswers":["Although the road was flooded, the driver remained calm."],"modelAnswer":"Although the road was flooded, the driver remained calm."}', '{"text":"Connect main and subordinate clauses without creating fragments or run-ons. Model correction: Although the road was flooded, the driver remained calm."}');
INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-p6-06','P6',6,'editing','Editing common grammar errors','Edit for agreement, countability, verb form, pronouns and clause structure.','{"rule":"Identify the error, explain the rule and make the smallest accurate correction.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for editing common grammar errors.","Apply editing common grammar errors accurately in context.","Edit a common error involving editing common grammar errors."]', '[{"label":"Accurate","sentence":"We need more furniture for the room."},{"label":"Needs editing","sentence":"We need more furnitures for the room."},{"label":"Correction","sentence":"We need more furniture for the room."}]', '["Avoid: We need more furnitures for the room.","Prefer: We need more furniture for the room."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
