INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-p6-07','P6',7,'text','Cohesion across sentences','Choose cohesive devices that express the real relationship between ideas.','{"rule":"Use reference words and connectors to make relationships between sentences clear.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for cohesion across sentences.","Apply cohesion across sentences accurately in context.","Edit a common error involving cohesion across sentences."]', '[{"label":"Accurate","sentence":"The team missed the bus. As a result, they arrived late."},{"label":"Needs editing","sentence":"The team missed the bus. However, they arrived late because of the delay."},{"label":"Correction","sentence":"The team missed the bus. As a result, they arrived late."}]', '["Avoid: The team missed the bus. However, they arrived late because of the delay.","Prefer: The team missed the bus. As a result, they arrived late."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
