INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-p6-07-b','gram-p6-07','P6','writing','editing','{"title":"Edit the sentence","prompt":"Correct this sentence without changing its meaning: The team missed the bus. However, they arrived late because of the delay.","modelText":"The team missed the bus. As a result, they arrived late.","speakFirst":false}', '{"acceptedAnswers":["The team missed the bus. As a result, they arrived late."],"modelAnswer":"The team missed the bus. As a result, they arrived late."}', '{"text":"Use reference words and connectors to make relationships between sentences clear. Model correction: The team missed the bus. As a result, they arrived late."}');
INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-p6-08','P6',8,'sentence','PSLE synthesis precision','Check grammar and meaning after every transformation.','{"rule":"Transform sentences accurately while preserving tense, meaning and required key words.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for psle synthesis precision.","Apply psle synthesis precision accurately in context.","Edit a common error involving psle synthesis precision."]', '[{"label":"Accurate","sentence":"Despite feeling tired, Aisha completed the task."},{"label":"Needs editing","sentence":"Despite Aisha was tired, she completed the task."},{"label":"Correction","sentence":"Despite feeling tired, Aisha completed the task."}]', '["Avoid: Despite Aisha was tired, she completed the task.","Prefer: Despite feeling tired, Aisha completed the task."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
