INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-s1-01','S1',1,'word and phrase','Expanding noun phrases','Build richer noun phrases with controlled modifiers.','{"rule":"Use premodifiers and postmodifiers to add precise information to nouns.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for expanding noun phrases.","Apply expanding noun phrases accurately in context.","Edit a common error involving expanding noun phrases."]', '[{"label":"Accurate","sentence":"The newly renovated library near the hall reopened today."},{"label":"Needs editing","sentence":"The library renovated newly near the hall reopened today."},{"label":"Correction","sentence":"The newly renovated library near the hall reopened today."}]', '["Avoid: The library renovated newly near the hall reopened today.","Prefer: The newly renovated library near the hall reopened today."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
