INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-s1-02','S1',2,'verb','Verb aspect: simple, progressive & perfect','Use aspect to show time relationships more precisely.','{"rule":"Choose aspect to show whether an action is habitual, ongoing or linked to another time.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for verb aspect: simple, progressive & perfect.","Apply verb aspect: simple, progressive & perfect accurately in context.","Edit a common error involving verb aspect: simple, progressive & perfect."]', '[{"label":"Accurate","sentence":"She has worked on the project for three weeks."},{"label":"Needs editing","sentence":"She works on the project for three weeks already."},{"label":"Correction","sentence":"She has worked on the project for three weeks."}]', '["Avoid: She works on the project for three weeks already.","Prefer: She has worked on the project for three weeks."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
