INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-s1-03','S1',3,'word and phrase','Preposition phrases as modifiers & adverbials','Use preposition phrases flexibly at phrase and sentence levels.','{"rule":"Use preposition phrases to add information about nouns or circumstances.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for preposition phrases as modifiers & adverbials.","Apply preposition phrases as modifiers & adverbials accurately in context.","Edit a common error involving preposition phrases as modifiers & adverbials."]', '[{"label":"Accurate","sentence":"The students in the front row listened carefully."},{"label":"Needs editing","sentence":"The students at the front row listened carefully."},{"label":"Correction","sentence":"The students in the front row listened carefully."}]', '["Avoid: The students at the front row listened carefully.","Prefer: The students in the front row listened carefully."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
