INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-s1-04','S1',4,'word and phrase','Adjectives, adverbs & degree','Control word class and degree for precise description.','{"rule":"Choose adjective or adverb forms according to what is being described.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for adjectives, adverbs & degree.","Apply adjectives, adverbs & degree accurately in context.","Edit a common error involving adjectives, adverbs & degree."]', '[{"label":"Accurate","sentence":"The athlete completed the course remarkably quickly."},{"label":"Needs editing","sentence":"The athlete completed the course remarkable quick."},{"label":"Correction","sentence":"The athlete completed the course remarkably quickly."}]', '["Avoid: The athlete completed the course remarkable quick.","Prefer: The athlete completed the course remarkably quickly."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
