INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-s1-05','S1',5,'sentence','Clause types & sentence variety','Use clause structures without double connectors or fragments.','{"rule":"Combine independent and dependent clauses to vary emphasis and rhythm.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for clause types & sentence variety.","Apply clause types & sentence variety accurately in context.","Edit a common error involving clause types & sentence variety."]', '[{"label":"Accurate","sentence":"Because the road was closed, we took another route."},{"label":"Needs editing","sentence":"Because the road was closed, so we took another route."},{"label":"Correction","sentence":"Because the road was closed, we took another route."}]', '["Avoid: Because the road was closed, so we took another route.","Prefer: Because the road was closed, we took another route."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
