INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-s1-06','S1',6,'sentence','Reported speech & viewpoint','Manage shifts in speaker, time and viewpoint.','{"rule":"Keep pronouns, tense and viewpoint consistent when reporting speech or thought.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for reported speech & viewpoint.","Apply reported speech & viewpoint accurately in context.","Edit a common error involving reported speech & viewpoint."]', '[{"label":"Accurate","sentence":"Farah explained that she had left her notes at home."},{"label":"Needs editing","sentence":"Farah explained that I have left my notes at home."},{"label":"Correction","sentence":"Farah explained that she had left her notes at home."}]', '["Avoid: Farah explained that I have left my notes at home.","Prefer: Farah explained that she had left her notes at home."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
