INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-s1-07','S1',7,'sentence','Voice: active, passive & emphasis','Use passive voice purposefully, not automatically.','{"rule":"Choose voice according to what information should receive emphasis.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for voice: active, passive & emphasis.","Apply voice: active, passive & emphasis accurately in context.","Edit a common error involving voice: active, passive & emphasis."]', '[{"label":"Accurate","sentence":"The results were announced after lunch."},{"label":"Needs editing","sentence":"The results announced after lunch."},{"label":"Correction","sentence":"The results were announced after lunch."}]', '["Avoid: The results announced after lunch.","Prefer: The results were announced after lunch."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
