INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-s1-08','S1',8,'text','Cohesion & paragraph links','Choose cohesive devices for meaning, not decoration.','{"rule":"Use pronouns, repetition, substitution and connectors to build coherent paragraphs.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for cohesion & paragraph links.","Apply cohesion & paragraph links accurately in context.","Edit a common error involving cohesion & paragraph links."]', '[{"label":"Accurate","sentence":"The trial failed twice. Nevertheless, the team continued refining the design."},{"label":"Needs editing","sentence":"The trial failed twice. Therefore, the team continued although there was no cause-and-effect link."},{"label":"Correction","sentence":"The trial failed twice. Nevertheless, the team continued refining the design."}]', '["Avoid: The trial failed twice. Therefore, the team continued although there was no cause-and-effect link.","Prefer: The trial failed twice. Nevertheless, the team continued refining the design."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
