INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-s2-01','S2',1,'sentence','Relative & non-finite clauses','Use reduced and full clauses accurately to add information.','{"rule":"Use relative and non-finite clauses to compress information and avoid repetition.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for relative & non-finite clauses.","Apply relative & non-finite clauses accurately in context.","Edit a common error involving relative & non-finite clauses."]', '[{"label":"Accurate","sentence":"Students hoping to join the trip must register by Friday."},{"label":"Needs editing","sentence":"Students hope to join the trip must register by Friday."},{"label":"Correction","sentence":"Students hoping to join the trip must register by Friday."}]', '["Avoid: Students hope to join the trip must register by Friday.","Prefer: Students hoping to join the trip must register by Friday."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
