INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-s2-02','S2',2,'sentence','Conditionals for real & imagined situations','Choose conditional forms according to likelihood and time.','{"rule":"Use conditional patterns to express general truths, real possibilities and imagined situations.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for conditionals for real & imagined situations.","Apply conditionals for real & imagined situations accurately in context.","Edit a common error involving conditionals for real & imagined situations."]', '[{"label":"Accurate","sentence":"If the proposal were cheaper, more people might support it."},{"label":"Needs editing","sentence":"If the proposal is cheaper yesterday, more people might support it."},{"label":"Correction","sentence":"If the proposal were cheaper, more people might support it."}]', '["Avoid: If the proposal is cheaper yesterday, more people might support it.","Prefer: If the proposal were cheaper, more people might support it."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
