INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-s2-03','S2',3,'sentence','Adverbials & fronting','Use fronted adverbials to organise information and emphasis.','{"rule":"Move adverbials to different positions to guide emphasis while keeping punctuation clear.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for adverbials & fronting.","Apply adverbials & fronting accurately in context.","Edit a common error involving adverbials & fronting."]', '[{"label":"Accurate","sentence":"After several failed attempts, the team changed its method."},{"label":"Needs editing","sentence":"After several failed attempts the team, changed its method."},{"label":"Correction","sentence":"After several failed attempts, the team changed its method."}]', '["Avoid: After several failed attempts the team, changed its method.","Prefer: After several failed attempts, the team changed its method."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
