INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-s2-04','S2',4,'verb','Modality & stance','Match modal strength to the evidence and purpose.','{"rule":"Use modal verbs and related expressions to show certainty, obligation, willingness and possibility.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for modality & stance.","Apply modality & stance accurately in context.","Edit a common error involving modality & stance."]', '[{"label":"Accurate","sentence":"The evidence may suggest a link, but it does not prove one."},{"label":"Needs editing","sentence":"The evidence must suggests a link, but it does not prove one."},{"label":"Correction","sentence":"The evidence may suggest a link, but it does not prove one."}]', '["Avoid: The evidence must suggests a link, but it does not prove one.","Prefer: The evidence may suggest a link, but it does not prove one."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
