INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-s2-05','S2',5,'editing','Agreement & editing in complex sentences','Use proximity and structure carefully in challenging agreement patterns.','{"rule":"Check agreement across longer noun phrases, clauses and coordinated structures.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for agreement & editing in complex sentences.","Apply agreement & editing in complex sentences accurately in context.","Edit a common error involving agreement & editing in complex sentences."]', '[{"label":"Accurate","sentence":"Neither the coach nor the players were ready to leave."},{"label":"Needs editing","sentence":"Neither the coach nor the players was ready to leave."},{"label":"Correction","sentence":"Neither the coach nor the players were ready to leave."}]', '["Avoid: Neither the coach nor the players was ready to leave.","Prefer: Neither the coach nor the players were ready to leave."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
