INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-s2-06','S2',6,'word and phrase','Nominalisation: turning actions into concepts','Recognise nominal forms and use them without making writing unnecessarily heavy.','{"rule":"Use nouns formed from verbs or adjectives when an abstract, formal style is appropriate.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for nominalisation: turning actions into concepts.","Apply nominalisation: turning actions into concepts accurately in context.","Edit a common error involving nominalisation: turning actions into concepts."]', '[{"label":"Accurate","sentence":"The committee decided quickly. The decision surprised everyone."},{"label":"Needs editing","sentence":"The committee decisioned quickly."},{"label":"Correction","sentence":"The committee decided quickly. The decision surprised everyone."}]', '["Avoid: The committee decisioned quickly.","Prefer: The committee decided quickly. The decision surprised everyone."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-s2-06-a','gram-s2-06','S2','writing','multiple_choice','{"title":"Choose the accurate sentence","prompt":"Which sentence best applies the rule for “Nominalisation: turning actions into concepts”?","options":["The committee decided quickly. The decision surprised everyone.","The committee decisioned quickly.","The committee decisioned quickly?","The committee decided quickly. The decision surprised everyone. Extra."],"audioText":null}', '{"correctOption":0,"acceptedAnswers":["The committee decided quickly. The decision surprised everyone."]}', '{"text":"Use nouns formed from verbs or adjectives when an abstract, formal style is appropriate."}');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-s2-06-b','gram-s2-06','S2','writing','editing','{"title":"Edit the sentence","prompt":"Correct this sentence without changing its meaning: The committee decisioned quickly.","modelText":"The committee decided quickly. The decision surprised everyone.","speakFirst":false}', '{"acceptedAnswers":["The committee decided quickly. The decision surprised everyone."],"modelAnswer":"The committee decided quickly. The decision surprised everyone."}', '{"text":"Use nouns formed from verbs or adjectives when an abstract, formal style is appropriate. Model correction: The committee decided quickly. The decision surprised everyone."}');
INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-s2-07','S2',7,'text','Grammar of recounts & explanations','Match grammar choices to whether a text recounts events or explains processes.','{"rule":"Choose tense, voice and connectors according to text purpose.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for grammar of recounts & explanations.","Apply grammar of recounts & explanations accurately in context.","Edit a common error involving grammar of recounts & explanations."]', '[{"label":"Accurate","sentence":"The valve opens when the pressure rises."},{"label":"Needs editing","sentence":"The valve opened when the pressure rises in a general explanation."},{"label":"Correction","sentence":"The valve opens when the pressure rises."}]', '["Avoid: The valve opened when the pressure rises in a general explanation.","Prefer: The valve opens when the pressure rises."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
