INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-s2-08','S2',8,'text','Conjunctive adverbs','Use conjunctive adverbs to connect complete ideas clearly.','{"rule":"Use conjunctive adverbs such as however, therefore and moreover with correct meaning and punctuation.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for conjunctive adverbs.","Apply conjunctive adverbs accurately in context.","Edit a common error involving conjunctive adverbs."]', '[{"label":"Accurate","sentence":"The cost increased. However, demand remained strong."},{"label":"Needs editing","sentence":"The cost increased, however demand remained strong."},{"label":"Correction","sentence":"The cost increased. However, demand remained strong."}]', '["Avoid: The cost increased, however demand remained strong.","Prefer: The cost increased. However, demand remained strong."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
