INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-s2-08-b','gram-s2-08','S2','writing','editing','{"title":"Edit the sentence","prompt":"Correct this sentence without changing its meaning: The cost increased, however demand remained strong.","modelText":"The cost increased. However, demand remained strong.","speakFirst":false}', '{"acceptedAnswers":["The cost increased. However, demand remained strong."],"modelAnswer":"The cost increased. However, demand remained strong."}', '{"text":"Use conjunctive adverbs such as however, therefore and moreover with correct meaning and punctuation. Model correction: The cost increased. However, demand remained strong."}');
INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-s3-01','S3',1,'verb','Advanced aspect & time relationships','Use perfect and progressive forms to make time relationships explicit.','{"rule":"Combine tense and aspect to show sequence, duration and completion accurately.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for advanced aspect & time relationships.","Apply advanced aspect & time relationships accurately in context.","Edit a common error involving advanced aspect & time relationships."]', '[{"label":"Accurate","sentence":"By the time the survey ended, researchers had collected 500 responses."},{"label":"Needs editing","sentence":"By the time the survey ended, researchers collected 500 responses already before it ended."},{"label":"Correction","sentence":"By the time the survey ended, researchers had collected 500 responses."}]', '["Avoid: By the time the survey ended, researchers collected 500 responses already before it ended.","Prefer: By the time the survey ended, researchers had collected 500 responses."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
