INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-s3-01-b','gram-s3-01','S3','writing','editing','{"title":"Edit the sentence","prompt":"Correct this sentence without changing its meaning: By the time the survey ended, researchers collected 500 responses already before it ended.","modelText":"By the time the survey ended, researchers had collected 500 responses.","speakFirst":false}', '{"acceptedAnswers":["By the time the survey ended, researchers had collected 500 responses."],"modelAnswer":"By the time the survey ended, researchers had collected 500 responses."}', '{"text":"Combine tense and aspect to show sequence, duration and completion accurately. Model correction: By the time the survey ended, researchers had collected 500 responses."}');
INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-s3-02','S3',2,'sentence','Passive choices & agent focus','Choose voice according to information focus.','{"rule":"Use passive voice when the process or receiver matters more than the agent; include the agent only when useful.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for passive choices & agent focus.","Apply passive choices & agent focus accurately in context.","Edit a common error involving passive choices & agent focus."]', '[{"label":"Accurate","sentence":"The samples were stored at a constant temperature."},{"label":"Needs editing","sentence":"At a constant temperature stored the samples."},{"label":"Correction","sentence":"The samples were stored at a constant temperature."}]', '["Avoid: At a constant temperature stored the samples.","Prefer: The samples were stored at a constant temperature."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-s3-02-a','gram-s3-02','S3','writing','multiple_choice','{"title":"Choose the accurate sentence","prompt":"Which sentence best applies the rule for “Passive choices & agent focus”?","options":["The samples were stored at a constant temperature.","At a constant temperature stored the samples.","At a constant temperature stored the samples?","The samples were stored at a constant temperature. Extra."],"audioText":null}', '{"correctOption":0,"acceptedAnswers":["The samples were stored at a constant temperature."]}', '{"text":"Use passive voice when the process or receiver matters more than the agent; include the agent only when useful."}');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-s3-02-b','gram-s3-02','S3','writing','editing','{"title":"Edit the sentence","prompt":"Correct this sentence without changing its meaning: At a constant temperature stored the samples.","modelText":"The samples were stored at a constant temperature.","speakFirst":false}', '{"acceptedAnswers":["The samples were stored at a constant temperature."],"modelAnswer":"The samples were stored at a constant temperature."}', '{"text":"Use passive voice when the process or receiver matters more than the agent; include the agent only when useful. Model correction: The samples were stored at a constant temperature."}');
INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-s3-03','S3',3,'sentence','Complex & mixed conditionals','Control time and reality across both clauses.','{"rule":"Use conditional forms consistently when talking about unreal pasts and present consequences.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for complex & mixed conditionals.","Apply complex & mixed conditionals accurately in context.","Edit a common error involving complex & mixed conditionals."]', '[{"label":"Accurate","sentence":"If we had left earlier, we would not be stuck in traffic now."},{"label":"Needs editing","sentence":"If we left earlier yesterday, we will not be stuck now."},{"label":"Correction","sentence":"If we had left earlier, we would not be stuck in traffic now."}]', '["Avoid: If we left earlier yesterday, we will not be stuck now.","Prefer: If we had left earlier, we would not be stuck in traffic now."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
