INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-s3-03-b','gram-s3-03','S3','writing','editing','{"title":"Edit the sentence","prompt":"Correct this sentence without changing its meaning: If we left earlier yesterday, we will not be stuck now.","modelText":"If we had left earlier, we would not be stuck in traffic now.","speakFirst":false}', '{"acceptedAnswers":["If we had left earlier, we would not be stuck in traffic now."],"modelAnswer":"If we had left earlier, we would not be stuck in traffic now."}', '{"text":"Use conditional forms consistently when talking about unreal pasts and present consequences. Model correction: If we had left earlier, we would not be stuck in traffic now."}');
INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-s3-04','S3',4,'sentence','Dummy subjects, fronting & inversion','Use marked structures purposefully and grammatically.','{"rule":"Use there/it, fronting and selected inversions to reorganise information and emphasis.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for dummy subjects, fronting & inversion.","Apply dummy subjects, fronting & inversion accurately in context.","Edit a common error involving dummy subjects, fronting & inversion."]', '[{"label":"Accurate","sentence":"There are several reasons why the plan failed."},{"label":"Needs editing","sentence":"Several reasons there are why the plan failed."},{"label":"Correction","sentence":"There are several reasons why the plan failed."}]', '["Avoid: Several reasons there are why the plan failed.","Prefer: There are several reasons why the plan failed."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-s3-04-a','gram-s3-04','S3','speaking','multiple_choice','{"title":"Choose the accurate sentence","prompt":"Which sentence best applies the rule for “Dummy subjects, fronting & inversion”?","options":["There are several reasons why the plan failed.","Several reasons there are why the plan failed.","Several reasons there are why the plan failed?","There are several reasons why the plan failed. Extra."],"audioText":null}', '{"correctOption":0,"acceptedAnswers":["There are several reasons why the plan failed."]}', '{"text":"Use there/it, fronting and selected inversions to reorganise information and emphasis."}');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-s3-04-b','gram-s3-04','S3','writing','editing','{"title":"Edit the sentence","prompt":"Correct this sentence without changing its meaning: Several reasons there are why the plan failed.","modelText":"There are several reasons why the plan failed.","speakFirst":false}', '{"acceptedAnswers":["There are several reasons why the plan failed."],"modelAnswer":"There are several reasons why the plan failed."}', '{"text":"Use there/it, fronting and selected inversions to reorganise information and emphasis. Model correction: There are several reasons why the plan failed."}');
INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-s3-05','S3',5,'word and phrase','Nominalisation for academic style','Use nominalisation to compress ideas, but avoid dense noun strings.','{"rule":"Use nominalisation to package processes as concepts while maintaining clarity.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for nominalisation for academic style.","Apply nominalisation for academic style accurately in context.","Edit a common error involving nominalisation for academic style."]', '[{"label":"Accurate","sentence":"The rapid expansion of the network created new risks."},{"label":"Needs editing","sentence":"The network expanded rapidly created new risks."},{"label":"Correction","sentence":"The rapid expansion of the network created new risks."}]', '["Avoid: The network expanded rapidly created new risks.","Prefer: The rapid expansion of the network created new risks."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
