INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-s3-06','S3',6,'text','Conjunctive adverbs & logical relations','Make the logical relation between sentences explicit and accurate.','{"rule":"Choose linking expressions that accurately signal contrast, cause, addition, concession or sequence.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for conjunctive adverbs & logical relations.","Apply conjunctive adverbs & logical relations accurately in context.","Edit a common error involving conjunctive adverbs & logical relations."]', '[{"label":"Accurate","sentence":"The sample was small; nevertheless, the pattern was consistent."},{"label":"Needs editing","sentence":"The sample was small; therefore, the pattern was consistent although size does not cause consistency."},{"label":"Correction","sentence":"The sample was small; nevertheless, the pattern was consistent."}]', '["Avoid: The sample was small; therefore, the pattern was consistent although size does not cause consistency.","Prefer: The sample was small; nevertheless, the pattern was consistent."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
