INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-s3-07','S3',7,'text','Grammar for argument & evaluation','Use grammar to signal stance, qualification and reasoning.','{"rule":"Use modality, concession and evidence clauses to present a measured argument.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for grammar for argument & evaluation.","Apply grammar for argument & evaluation accurately in context.","Edit a common error involving grammar for argument & evaluation."]', '[{"label":"Accurate","sentence":"Although the policy has benefits, its long-term cost may be difficult to justify."},{"label":"Needs editing","sentence":"Although the policy has benefits, but its long-term cost may be difficult to justify."},{"label":"Correction","sentence":"Although the policy has benefits, its long-term cost may be difficult to justify."}]', '["Avoid: Although the policy has benefits, but its long-term cost may be difficult to justify.","Prefer: Although the policy has benefits, its long-term cost may be difficult to justify."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
