INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-s3-08','S3',8,'sentence','Parallelism & controlled sentence patterns','Use parallel structures to make lists and comparisons clear.','{"rule":"Keep coordinated items in the same grammatical form.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for parallelism & controlled sentence patterns.","Apply parallelism & controlled sentence patterns accurately in context.","Edit a common error involving parallelism & controlled sentence patterns."]', '[{"label":"Accurate","sentence":"The programme aims to reduce waste, save energy and improve access."},{"label":"Needs editing","sentence":"The programme aims to reduce waste, saving energy and improved access."},{"label":"Correction","sentence":"The programme aims to reduce waste, save energy and improve access."}]', '["Avoid: The programme aims to reduce waste, saving energy and improved access.","Prefer: The programme aims to reduce waste, save energy and improve access."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
