INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-s4-01','S4',1,'editing','Precision, concision & grammatical choice','Edit grammar and structure for precise, economical expression.','{"rule":"Choose structures that express the same meaning with less clutter and greater precision.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for precision, concision & grammatical choice.","Apply precision, concision & grammatical choice accurately in context.","Edit a common error involving precision, concision & grammatical choice."]', '[{"label":"Accurate","sentence":"The committee postponed the meeting because two reports were incomplete."},{"label":"Needs editing","sentence":"Due to the fact that two reports were incomplete, the committee made a postponement of the meeting."},{"label":"Correction","sentence":"The committee postponed the meeting because two reports were incomplete."}]', '["Avoid: Due to the fact that two reports were incomplete, the committee made a postponement of the meeting.","Prefer: The committee postponed the meeting because two reports were incomplete."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-s4-01-a','gram-s4-01','S4','reading','multiple_choice','{"title":"Choose the accurate sentence","prompt":"Which sentence best applies the rule for “Precision, concision & grammatical choice”?","options":["The committee postponed the meeting because two reports were incomplete.","Due to the fact that two reports were incomplete, the committee made a postponement of the meeting.","Due to the fact that two reports were incomplete, the committee made a postponement of the meeting?","The committee postponed the meeting because two reports were incomplete. Extra."],"audioText":null}', '{"correctOption":0,"acceptedAnswers":["The committee postponed the meeting because two reports were incomplete."]}', '{"text":"Choose structures that express the same meaning with less clutter and greater precision."}');
