INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-s4-02','S4',2,'sentence','Clause control in sophisticated sentences','Keep the main clause visible in complex sentences.','{"rule":"Use embedding and subordination without losing the main clause or creating ambiguity.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for clause control in sophisticated sentences.","Apply clause control in sophisticated sentences accurately in context.","Edit a common error involving clause control in sophisticated sentences."]', '[{"label":"Accurate","sentence":"The proposal, which was revised after consultation, was finally approved."},{"label":"Needs editing","sentence":"The proposal which was revised after consultation, finally approved."},{"label":"Correction","sentence":"The proposal, which was revised after consultation, was finally approved."}]', '["Avoid: The proposal which was revised after consultation, finally approved.","Prefer: The proposal, which was revised after consultation, was finally approved."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
