INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-s4-03','S4',3,'sentence','Information structure: fronting & inversion','Use inversion after certain fronted limiting expressions.','{"rule":"Reorder sentence elements for emphasis while preserving standard patterns.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for information structure: fronting & inversion.","Apply information structure: fronting & inversion accurately in context.","Edit a common error involving information structure: fronting & inversion."]', '[{"label":"Accurate","sentence":"Only after the audit did the team discover the error."},{"label":"Needs editing","sentence":"Only after the audit the team discovered the error."},{"label":"Correction","sentence":"Only after the audit did the team discover the error."}]', '["Avoid: Only after the audit the team discovered the error.","Prefer: Only after the audit did the team discover the error."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
