INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-s4-04','S4',4,'text','Modality, hedging & evaluative stance','Avoid stronger certainty than the evidence supports.','{"rule":"Adjust certainty with modal verbs, adverbs and reporting verbs according to evidence.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for modality, hedging & evaluative stance.","Apply modality, hedging & evaluative stance accurately in context.","Edit a common error involving modality, hedging & evaluative stance."]', '[{"label":"Accurate","sentence":"The findings suggest that the intervention may be effective."},{"label":"Needs editing","sentence":"The findings prove that the intervention will definitely work forever."},{"label":"Correction","sentence":"The findings suggest that the intervention may be effective."}]', '["Avoid: The findings prove that the intervention will definitely work forever.","Prefer: The findings suggest that the intervention may be effective."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-s4-04-a','gram-s4-04','S4','speaking','multiple_choice','{"title":"Choose the accurate sentence","prompt":"Which sentence best applies the rule for “Modality, hedging & evaluative stance”?","options":["The findings suggest that the intervention may be effective.","The findings prove that the intervention will definitely work forever.","The findings prove that the intervention will definitely work forever?","The findings suggest that the intervention may be effective. Extra."],"audioText":null}', '{"correctOption":0,"acceptedAnswers":["The findings suggest that the intervention may be effective."]}', '{"text":"Adjust certainty with modal verbs, adverbs and reporting verbs according to evidence."}');
