INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-s4-05','S4',5,'text','Cohesion across extended texts','Use varied cohesive resources across longer texts.','{"rule":"Create reference chains and logical links across paragraphs without repetitive connectors.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for cohesion across extended texts.","Apply cohesion across extended texts accurately in context.","Edit a common error involving cohesion across extended texts."]', '[{"label":"Accurate","sentence":"This concern is important. It also explains why the final recommendation is cautious."},{"label":"Needs editing","sentence":"This concern is important. Moreover, moreover, however the final recommendation is cautious."},{"label":"Correction","sentence":"This concern is important. It also explains why the final recommendation is cautious."}]', '["Avoid: This concern is important. Moreover, moreover, however the final recommendation is cautious.","Prefer: This concern is important. It also explains why the final recommendation is cautious."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
