INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-s4-06','S4',6,'editing','Editing ambiguity & misplaced modifiers','Check who or what a modifying phrase logically describes.','{"rule":"Place modifiers close to what they modify so the intended meaning is unmistakable.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for editing ambiguity & misplaced modifiers.","Apply editing ambiguity & misplaced modifiers accurately in context.","Edit a common error involving editing ambiguity & misplaced modifiers."]', '[{"label":"Accurate","sentence":"Walking to school, I noticed the new mural."},{"label":"Needs editing","sentence":"Walking to school, the new mural caught my attention."},{"label":"Correction","sentence":"Walking to school, I noticed the new mural."}]', '["Avoid: Walking to school, the new mural caught my attention.","Prefer: Walking to school, I noticed the new mural."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
