INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-s4-07','S4',7,'text','Grammar of persuasive & discursive texts','Use grammar to manage counterpoints and qualification.','{"rule":"Use concession, contrast, modality and evidence clauses to build balanced arguments.","whyItMatters":"Grammar is learned in context so that form supports meaning, purpose and audience.","studySteps":["Read the rule and examples.","Notice what changes the meaning or grammaticality.","Complete the exercises.","Revisit the topic when mastery is below 80%."]}', '["Explain the key rule for grammar of persuasive & discursive texts.","Apply grammar of persuasive & discursive texts accurately in context.","Edit a common error involving grammar of persuasive & discursive texts."]', '[{"label":"Accurate","sentence":"While the scheme is costly, it could produce substantial long-term benefits."},{"label":"Needs editing","sentence":"While the scheme is costly, but it could produce substantial long-term benefits."},{"label":"Correction","sentence":"While the scheme is costly, it could produce substantial long-term benefits."}]', '["Avoid: While the scheme is costly, but it could produce substantial long-term benefits.","Prefer: While the scheme is costly, it could produce substantial long-term benefits."]', 'Aligned to Singapore MOE English Language Syllabus 2020 grammar progression; examples are original English Mastery content.');
